const body = ($('Webhook').first().json.body) || {};
const question = String(body.question || body.prompt || body.message || '').trim();
if (!question) {
  return [{ json: { valid: false, error: 'Missing required field: question', prompt: '' } }];
}
const stored = $input.first() ? ($input.first().json || {}) : {};
const fromBody = (typeof body.pdfText === 'string') ? body.pdfText.trim() : '';
const fromStore = (typeof stored.pdf_text === 'string') ? stored.pdf_text.trim() : '';
const pdfText = fromBody || fromStore;
const mentionsPdf = /\b(pdf|uploaded|upload|document|file)\b/i.test(question) || fromBody !== '';
if (mentionsPdf) {
  if (!pdfText) {
    return [{ json: { valid: false, error: 'No PDF text is available. Please upload a PDF first, then ask for the content again.', prompt: '' } }];
  }
  const prompt = 'Use ONLY the PDF text below. Do not use outside knowledge.\n\nPDF TEXT:\n' + pdfText + '\n\nREQUEST:\n' + question;
  return [{ json: { valid: true, usesPdf: true, error: '', prompt } }];
}
return [{ json: { valid: true, usesPdf: false, error: '', prompt: question } }];
